sap.ui.define([
    "sap/m/MessageToast"
], function (MessageToast) {
    "use strict";

    async function onDownloadPDFCartaAnual(oController, sButtonId, data) {
        try {
            await oController._ensurePdfToolkit();
            await oController._ensureMDFData();
            
            const PDFLibRef = window.PDFLib || oController._pdfLibRef;
            const html2canvasRef = window.html2canvas || oController._html2canvasRef;

            if (!PDFLibRef || !html2canvasRef) {
                throw new Error("No se pudieron cargar las bibliotecas PDF/Canvas requeridas.");
            }

            let aUsers;
            if (data) {
                aUsers = data;
            } else {
                aUsers = oController.getSelectedUsers();
            }
            
            console.log(data);
            
            if (aUsers.length === 0) {
                MessageToast.show("Seleccione al menos un colaborador.");
                return;
            }

            for (let i = 0; i < aUsers.length; i++) {
                const user = aUsers[i];

                if (aUsers.length > 1) {
                    MessageToast.show(`Generando documento ${i + 1} de ${aUsers.length}...`);
                }

                // obtengo paycompValue
                user.paycompValue = user?.empInfo?.compInfoNav?.results?.[0]?.empPayCompRecurringNav?.results?.[0]?.paycompvalue || 0;
                console.log("user anual usuario", user);

                // obtengo la fecha de inicio
                let rawStartDate;
                if (user.empInfo) {
                    rawStartDate = user.hireDate;
                } else {
                    rawStartDate = user.hireDateRaw;
                }

                let fechaInicio = "fecha no disponible";
                let antiguedadAnios = 0;

                if (rawStartDate && !isNaN(Date.parse(rawStartDate))) {
                    const fechaInicioObj = new Date(new Date(rawStartDate).setDate(new Date(rawStartDate).getDate() + 1));
                    const fechaActual = new Date();
                    antiguedadAnios = fechaActual.getFullYear() - fechaInicioObj.getFullYear();
                    const mesDiff = fechaActual.getMonth() - fechaInicioObj.getMonth();
                    if (mesDiff < 0 || (mesDiff === 0 && fechaActual.getDate() < fechaInicioObj.getDate())) {
                        antiguedadAnios--;
                    }

                    const dia = fechaInicioObj.getDate();
                    const mes = fechaInicioObj.toLocaleString("es-ES", { month: "long" }).toLowerCase();
                    const anio = fechaInicioObj.getFullYear();
                    fechaInicio = `${dia} de ${mes} del año ${anio}`;
                }

                // aplico el factor salarial desde oController.aMDF
                let salarioBase = Number(user.paycompvalue);
                let factor = 1;
                const mdf = oController.aMDF?.[0] || {};

                if (antiguedadAnios >= 0 && antiguedadAnios <= 2) {
                    factor = parseFloat(mdf.cust_factorSalarial_0_2);
                } else if (antiguedadAnios >= 3 && antiguedadAnios <= 4) {
                    factor = parseFloat(mdf.cust_factorSalarial_3_4);
                } else if (antiguedadAnios >= 5 && antiguedadAnios <= 9) {
                    factor = parseFloat(mdf.cust_factorSalarial_5_9);
                } else if (antiguedadAnios >= 10 && antiguedadAnios <= 15) {
                    factor = parseFloat(mdf.cust_factorSalarial_10_15);
                } else if (antiguedadAnios >= 16 && antiguedadAnios <= 20) {
                    factor = parseFloat(mdf.cust_factorSalarial_16_20);
                } else if (antiguedadAnios >= 21 && antiguedadAnios <= 24) {
                    factor = parseFloat(mdf.cust_factorSalarial_21_24);
                } else if (antiguedadAnios >= 25) {
                    factor = parseFloat(mdf.cust_factorSalarial_25);
                }

                // salario ajustado
                const salarioBase1 = Number(user.paycompvalue || user.paycompValue || 0);
                const salarioAjustado = salarioBase1 * factor;
                const sal = salarioAjustado.toLocaleString('en-US', { 
                    minimumFractionDigits: 2, 
                    maximumFractionDigits: 2 
                });

                // fecha actual
                const fechaAhora = new Date();
                const fechaAAActual = `${fechaAhora.getDate()} del mes de ${fechaAhora.toLocaleString('es-ES', { month: 'long' })} del ${fechaAhora.getFullYear()}`;
                
                // variables auxiliares
                const position = user.jobCode ? user.jobCode.replace(/\s?\(.*?\)/, '') : "posición no especificada";
                const division = user.division ? user.division.replace(/\s?\(.*?\)/, '') : "área no especificada";
                const secondP = user.secondLastName ? user.secondLastName : "";

                // genero un HTML del documento
                const htmlRaw = `
                    <p><br></p>
                    <p><br></p>
                    <p style="text-align: center;"><span style="font-size:12.300000190734862pt;font-family:Arial,sans-serif;"><strong>A QUIEN PUEDA INTERESAR</strong></span></p>
                    <p><br></p>
                    <p><br></p>
                    <p style="text-align: justify;"><span style="font-size:12.300000190734862pt;font-family:Arial,sans-serif;">Por este medio certificamos que el/la
                    <strong> ${user.salut} ${user.firstName} ${user.lastName} ${secondP},</strong>
                    portador(a) de la Cédula de Identidad y Electoral No.<strong>${user.nationalId}</strong>, labora en esta empresa desde el <strong>${fechaInicio}</strong>, desempeñando el cargo de 
                    <strong>${(user.title && user.title.replace(/\s?\(.*?\)/, '')) || 'COMPLETAR'}</strong>, en la dirección de <strong>${division}</strong>. Devengando un salario anual garantizado de <strong>RD$${sal}</strong></span></p>
                    <p><br></p>
                    <p><br></p>
                    <p><span style="font-size:12.300000190734862pt;font-family:Arial,sans-serif;">Se expide la presente certificación, a solicitud de la parte interesada al día ${fechaAAActual}</span></p>
                    <p><br></p>
                    <p><br></p>
                    <p><span style="font-size:12.300000190734862pt;font-family:Arial,sans-serif;">Atentamente,</span></p>
                    <p><br></p>
                    <p style="margin: auto 0px;padding: 0px;font-weight: normal;font-style: normal;vertical-align: baseline;background-color: transparent;color: windowtext;text-align: left;text-indent: 0px;"><img src="data:image/png;base64," style="width: 166px; height: 78.1693px;"></p>
                    <p style="margin: auto 0px;padding: 0px;font-weight: normal;font-style: normal;vertical-align: baseline;background-color: transparent;color: windowtext;text-align: left;text-indent: 0px;"><span style="margin: 0px;padding: 0px;color: rgb(0, 0, 0);font-size:14px;line-height: 18.3458px;font-family: Arial, Arial_EmbeddedFont, Arial_MSFontService, sans-serif;font-weight: bold;"><span style="margin: 0px;padding: 0px;">Ivelisse </span><span style="margin: 0px;padding: 0px;border-bottom: 1px solid transparent;">Queliz</span></span><span style="margin: 0px;padding: 0px;font-size:14px;line-height: 18.3458px;font-family: Arial, Arial_EmbeddedFont, Arial_MSFontService, sans-serif;color: rgb(0, 0, 0);">&nbsp;</span></p>
                    <p style="margin: auto 0px;padding: 0px;font-weight: normal;font-style: normal;vertical-align: baseline;background-color: transparent;color: windowtext;text-align: left;text-indent: 0px;"><span style="margin: 0px;padding: 0px;font-size:14px;line-height: 18.3458px;font-family: Arial, Arial_EmbeddedFont, Arial_MSFontService, sans-serif;"><span style="margin: 0px;padding: 0px;">Gerente Compensación y Beneficios</span></span><span style="margin: 0px;padding: 0px;font-size:14px;line-height: 18.3458px;font-family: Arial, Arial_EmbeddedFont, Arial_MSFontService, sans-serif;">&nbsp;</span></p>
                                <p style="margin: auto 0px;padding: 0px;font-weight: normal;font-style: normal;vertical-align: baseline;background-color: transparent;color: windowtext;text-align: left;text-indent: 0px;"><img src="data:image/png;base64," style="width:147px;height:57px;"></p>
                    `;

                if (sButtonId === "container-gestordoccolombia---View1--wordDataInfo") {
                    const header = `
                        <html xmlns:o='urn:schemas-microsoft-com:office:office'
                              xmlns:w='urn:schemas-microsoft-com:office:word'
                              xmlns='http://www.w3.org/TR/REC-html40'>
                        <head><meta charset='utf-8'><title>Documento Word</title></head><body>
                        <p><br></p>`;
                    const footer = "</body></html>";
                    
                    const htmlRaw2 = `
                        <p><br></p>
                        <p><br></p>
                        <p style="text-align: center;"><span style="font-size:12.300000190734862pt;font-family:Arial,sans-serif;"><strong>A QUIEN PUEDA INTERESAR</strong></span></p>
                        <p><br></p>
                        <p><br></p>
                        <p style="text-align: justify;"><span style="font-size:12.300000190734862pt;font-family:Arial,sans-serif;">Por este medio certificamos que el/la
                        <strong> ${user.salut} ${user.firstName} ${user.lastName} ${secondP},</strong>
                        portador(a) de la Cédula de Identidad y Electoral No.<strong>${user.nationalId}</strong>, labora en esta empresa desde el <strong>${fechaInicio}</strong>, desempeñando el cargo de 
                        <strong>${(user.title && user.title.replace(/\s?\(.*?\)/, '')) || 'COMPLETAR'}</strong>, en la dirección de <strong>${division}</strong>. Devengando un salario anual garantizado de <strong>RD$${sal}</strong></span></p>
                        <p><br></p>
                        <p><span style="font-size:12.300000190734862pt;font-family:Arial,sans-serif;">Se expide la presente certificación, a solicitud de la parte interesada al día <strong>${fechaAAActual}</strong></span></p>
                        <p><br></p>
                        <p><span style="font-size:12.300000190734862pt;font-family:Arial,sans-serif;">Atentamente,</span></p>
                        <p><br></p>
                        <p><br></p>
                        <p><br></p>
                        <p style='margin-right:0cm;margin-left:0cm;font-size:16px;font-family:"Times New Roman",serif;margin:0cm;'><strong><span style='font-size:14px;font-family:"Arial",sans-serif;color:black;'>Ivelisse Queliz</span></strong></p>
                        <p style='margin-right:0cm;margin-left:0cm;font-size:16px;font-family:"Times New Roman",serif;margin:0cm;'><span style='font-size:14px;font-family:"Arial",sans-serif;'>Gerente Compensación y Beneficios</span></p>`;

                    const fullHTML = header + htmlRaw2 + footer;

                    const blob = new Blob(['\ufeff', fullHTML], {
                        type: "application/msword"
                    });
                    
                    const fileName = `${user.firstName}_${user.lastName}_Carta_Anual.doc`;
                    const link = document.createElement("a");
                    link.href = URL.createObjectURL(blob);
                    link.download = fileName;
                    document.body.appendChild(link);
                    link.click();
                    
                    document.body.removeChild(link);
                    URL.revokeObjectURL(link.href);

                } else {
                    const contentBlocks = htmlRaw.split("<!--PAGEBREAK-->");
                    const existingPdfBytes = await fetch("pdf/hojaMetaldom.pdf").then(res => res.arrayBuffer());
                    const pdfDoc = await PDFLibRef.PDFDocument.load(existingPdfBytes);
                    const [templatePage] = pdfDoc.getPages();
                    const { width, height } = templatePage.getSize();
                    const templatePageImage = await pdfDoc.embedPage(templatePage);

                    for (const blockHtml of contentBlocks) {
                        const div = document.createElement("div");
                        div.style.width = "794px";
                        div.style.height = "760px";
                        div.style.padding = "40px";
                        div.style.backgroundColor = "white";
                        div.style.fontSize = "12px";
                        div.style.boxSizing = "border-box";
                        div.style.position = "absolute";
                        div.style.top = "-9999px";
                        div.innerHTML = blockHtml;
                        document.body.appendChild(div);

                        const canvas = await html2canvasRef(div, {
                            scale: 2,
                            useCORS: true
                        });
                        const imgData = canvas.toDataURL("image/png");
                        
                        document.body.removeChild(div);

                        const img = await pdfDoc.embedPng(imgData);
                        const newPage = pdfDoc.addPage([width, height]);
                        newPage.drawPage(templatePageImage);

                        const imgWidth = width * 0.9;
                        const imgHeight = (img.height * imgWidth) / img.width;

                        newPage.drawImage(img, {
                            x: (width - imgWidth) / 2,
                            y: height - imgHeight - 130,
                            width: imgWidth,
                            height: imgHeight,
                        });
                    }

                    pdfDoc.removePage(0);

                    const pdfBytes = await pdfDoc.save();
                    const fileName = `${user.firstName}_${user.lastName}_Carta_Anual.pdf`;

                    const blob = new Blob([pdfBytes], { type: "application/pdf" });
                    const link = document.createElement("a");
                    link.href = URL.createObjectURL(blob);
                    link.download = fileName;
                    link.click();

                    URL.revokeObjectURL(link.href);
                }
            }

            const mensaje = aUsers.length > 1
                ? `${aUsers.length} documentos generados correctamente.`
                : "Documento generado correctamente.";
            MessageToast.show(mensaje);

        } catch (error) {
            console.error("Error generando el documento:", error);
            MessageToast.show("Error generando el documento: " + error.message);
        }
    }

    return {
        onDownloadPDFCartaAnual
    };
});